// Decode an Ourea ?format=capnp ForecastResponse in Kotlin, with the
// capnproto-java runtime and bindings generated by gen.sh.
import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    kotlin("jvm") version "2.4.21"
    application
}

repositories { mavenCentral() }

dependencies {
    // Keep in step with CAPNP_JAVA_TAG in gen.sh.
    implementation("org.capnproto:runtime:0.1.16")
}

java { targetCompatibility = JavaVersion.VERSION_17 }
kotlin { compilerOptions { jvmTarget.set(JvmTarget.JVM_17) } }
tasks.withType<JavaCompile>().configureEach { options.release.set(17) }

sourceSets { main { java.srcDir("build/generated/java") } }

application { mainClass.set("DecodeForecastKt") }
